#include "unity.h"
#include "buffer.h"
#include "helpers.h"
#include "malloc_wrap.h"

void setUp(void) { }
void tearDown(void) { malloc_reset(); }

void unit_test_buffer_prepend_resize_failure(void) {
    // Setup: create a buffer with small capacity and some initial data
    // We want self->len <= needed so that resize is triggered
    // helper_make_buffer_with_data allocates a buffer with len = strlen(str)
    // To ensure resize is needed, we create a buffer with "abc" (len=3)
    // and try to prepend "xyz" (len=3), so needed=6, but buffer->len=3
    buffer_t *buf = buffer_new_with_size(3);
    TEST_ASSERT_NOT_NULL(buf);
    memcpy(buf->data, "abc", 4); // include null terminator

    // There are 2 allocations in setup: buffer_new_with_size (malloc + calloc)
    // The next allocation is the realloc in buffer_resize, which we want to fail
    malloc_fail_after(2);

    int ret = buffer_prepend(buf, "xyz");
    TEST_ASSERT_EQUAL_INT(-1, ret);

    // The buffer should remain unchanged
    helper_assert_buffer_string_equals(buf, "abc");

    // Cleanup
    buffer_free(buf);
}

int main(void) {
    UNITY_BEGIN();
    RUN_TEST(unit_test_buffer_prepend_resize_failure);
    return UNITY_END();
}

